# -*- coding: utf-8 -*-
# Catechism bank — the ʿalāqa question sheet, items 25–47 (the remaining relations of the majāz mursal).
ITEMS = [
 {"n": 25, "q": {"tr": "Müsebbebiyyet alâkası nedir?", "en": "What is the relation of musabbabiyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâ için müsebbeb olmasıdır: أَمْطَرَتِ السَّمَاءُ نَبَاتًا — نَبَات mecazdır; hakikî mânâsı ot, mecâzî mânâsı yağmur; ot yağmurun müsebbebidir. Karine: أَمْطَرَتْ'in nebâta taallûku — ot yağmaz. İfade: ذِكْرُ الْمُسَبَّبِ إِرَادَةُ السَّبَبِ.", "en": "The literal sense is the effect of the figurative: أَمْطَرَتِ السَّمَاءُ نَبَاتًا — نَبَات is a majāz; literal the herbage, figurative the rain; herbage is what rain causes. Clue: herbage does not rain down. Formula: ذِكْرُ الْمُسَبَّبِ إِرَادَةُ السَّبَبِ."},
  "ar": ["أَمْطَرَتِ السَّمَاءُ نَبَاتًا", "ذِكْرُ الْمُسَبَّبِ إِرَادَةُ السَّبَبِ"], "notes": ["majaz-mursal"]},
 {"n": 26, "q": {"tr": "Kevn-i sâbık alâkası nedir?", "en": "What is the relation of kawn sābiq?"},
  "a": {"tr": "Hakikî mânânın, hüküm zamanı itibariyle mecâzî mânâdan önce olmasıdır: وَآتُوا الْيَتَامَى أَمْوَالَهُمْ — يَتَامَى mecazdır; hakikî mânâsı yetimler, mecâzî mânâsı erginler; yetimlik, erginlikten önce geçmiştir. Karine: âyetin mâba'di — mal yetime verilmez. İfade: ذِكْرُ الْمَاضِي إِرَادَةُ الْحَالِ.", "en": "The literal sense preceded the figurative in time: وَآتُوا الْيَتَامَى أَمْوَالَهُمْ — يَتَامَى is a majāz; literal the orphans, figurative grown men; orphanhood came before manhood. Clue: property is not handed to an orphan. Formula: ذِكْرُ الْمَاضِي إِرَادَةُ الْحَالِ."},
  "ar": ["وَآتُوا الْيَتَامَى أَمْوَالَهُمْ", "ذِكْرُ الْمَاضِي إِرَادَةُ الْحَالِ"], "notes": ["majaz-mursal"]},
 {"n": 27, "q": {"tr": "Kevn-i lâhık alâkası nedir?", "en": "What is the relation of kawn lāḥiq?"},
  "a": {"tr": "Hakikî mânânın gelecek zamanda mecâzî mânâya lâhık ve ârız olmasıdır: إِنِّي أَرَانِي أَعْصِرُ خَمْرًا — خَمْر mecazdır; hakikî mânâsı şarap, mecâzî mânâsı üzüm suyu; şarap, üzüm suyuna sonradan ârız olacaktır. Karine: أَعْصِرُ'nun hamra taallûku — şarap sıkılmaz, şıra sıkılır. İfade: ذِكْرُ الِاسْتِقْبَالِ إِرَادَةُ الْحَالِ.", "en": "The literal sense will come upon the figurative later: إِنِّي أَرَانِي أَعْصِرُ خَمْرًا — خَمْر is a majāz; literal wine, figurative grape-juice; wine is what the juice becomes. Clue: wine is not pressed. Formula: ذِكْرُ الِاسْتِقْبَالِ إِرَادَةُ الْحَالِ."},
  "ar": ["إِنِّي أَرَانِي أَعْصِرُ خَمْرًا", "ذِكْرُ الِاسْتِقْبَالِ إِرَادَةُ الْحَالِ"], "notes": ["majaz-mursal"]},
 {"n": 28, "q": {"tr": "Mahalliyyet alâkası nedir?", "en": "What is the relation of maḥalliyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâya mahal olmasıdır: وَاسْأَلِ الْقَرْيَةَ — قَرْيَة mecazdır; hakikî mânâsı köy, mecâzî mânâsı köy halkı; köy, halkının mahallidir. Karine: اسْأَلْ'in karyeye taallûku — köye sorulmaz, halkına sorulur. İfade: ذِكْرُ الْمَحَلِّ إِرَادَةُ الْحَالِّ.", "en": "The literal sense is the place of the figurative: وَاسْأَلِ الْقَرْيَةَ — قَرْيَة is a majāz; literal the town, figurative its people; the town is where they dwell. Clue: one asks people, not a town. Formula: ذِكْرُ الْمَحَلِّ إِرَادَةُ الْحَالِّ."},
  "ar": ["وَاسْأَلِ الْقَرْيَةَ", "ذِكْرُ الْمَحَلِّ إِرَادَةُ الْحَالِّ"], "notes": ["majaz-mursal"]},
 {"n": 29, "q": {"tr": "Hâlliyyet alâkası nedir?", "en": "What is the relation of ḥālliyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâda mevcut olmasıdır: فَفِي رَحْمَةِ اللهِ — رَحْمَة mecazdır; hakikî mânâsı rahmet, mecâzî mânâsı cennet; rahmet cennette mevcuttur. Karine: zarfiyyet için olan فِي — rahmete girilmez, rahmetin bulunduğu cennete girilir. İfade: ذِكْرُ الْحَالِّ إِرَادَةُ الْمَحَلِّ.", "en": "The literal sense dwells in the figurative: فَفِي رَحْمَةِ اللهِ — رَحْمَة is a majāz; literal mercy, figurative the Garden; mercy dwells in the Garden. Clue: the فِي of containment — one enters the Garden, not mercy. Formula: ذِكْرُ الْحَالِّ إِرَادَةُ الْمَحَلِّ."},
  "ar": ["فَفِي رَحْمَةِ اللهِ", "ذِكْرُ الْحَالِّ إِرَادَةُ الْمَحَلِّ"], "notes": ["majaz-mursal"]},
 {"n": 30, "q": {"tr": "Âliyyet alâkası nedir?", "en": "What is the relation of āliyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâya âlet olmasıdır: وَاجْعَلْ لِي لِسَانَ صِدْقٍ فِي الْآخِرِينَ — لِسَان mecazdır; hakikî mânâsı dil, mecâzî mânâsı güzel anılma (zikr-i sâdık); dil, zikrin âletidir. Karine: lisânın فِي ile sonrakilere nisbeti — sonrakilerde dil olmaz, zikir olur. İfade: ذِكْرُ الْآلَةِ إِرَادَةُ ذِي الْآلَةِ.", "en": "The literal sense is the instrument of the figurative: وَاجْعَلْ لِي لِسَانَ صِدْقٍ فِي الْآخِرِينَ — لِسَان is a majāz; literal the tongue, figurative a good name; the tongue is the instrument of mention. Clue: among later generations there is mention, not a tongue. Formula: ذِكْرُ الْآلَةِ إِرَادَةُ ذِي الْآلَةِ."},
  "ar": ["وَاجْعَلْ لِي لِسَانَ صِدْقٍ فِي الْآخِرِينَ", "ذِكْرُ الْآلَةِ إِرَادَةُ ذِي الْآلَةِ"], "notes": ["majaz-mursal"]},
 {"n": 31, "q": {"tr": "Itlak alâkası nedir?", "en": "What is the relation of iṭlāq?"},
  "a": {"tr": "Hakikî mânânın mutlak, mecâzî mânânın mukayyed olmasıdır: نِعْمَ الْإِبِلُ لَكِنَّهُ غَلِيظُ الشَّفَةِ — شَفَة mecazdır; hakikî mânâsı mutlak dudak, mecâzî mânâsı deve dudağı (مِشْفَر). Karine: إِبِل'in zikri — devede mutlak dudak değil deve dudağı olur. İfade: ذِكْرُ الْمُطْلَقِ إِرَادَةُ الْمُقَيَّدِ.", "en": "The literal sense is unrestricted, the figurative restricted: نِعْمَ الْإِبِلُ لَكِنَّهُ غَلِيظُ الشَّفَةِ — شَفَة is a majāz; literal a lip in general, figurative a camel's lip (مِشْفَر). Clue: the camel is named. Formula: ذِكْرُ الْمُطْلَقِ إِرَادَةُ الْمُقَيَّدِ."},
  "ar": ["نِعْمَ الْإِبِلُ لَكِنَّهُ غَلِيظُ الشَّفَةِ"], "notes": ["majaz-mursal"]},
 {"n": 32, "q": {"tr": "Takyid alâkası nedir?", "en": "What is the relation of taqyīd?"},
  "a": {"tr": "Hakikî mânânın mukayyed, mecâzî mânânın mutlak olmasıdır: لَكِنَّكَ زَنْجِيٌّ غَلِيظُ الْمَشَافِرِ — مَشَافِر mecazdır; hakikî mânâsı deve dudağı, mecâzî mânâsı mutlak dudak. Karine: زَنْجِيّ'nin zikri — zencide insan dudağı olur. İfade: ذِكْرُ الْمُقَيَّدِ إِرَادَةُ الْمُطْلَقِ.", "en": "The literal sense is restricted, the figurative unrestricted: لَكِنَّكَ زَنْجِيٌّ غَلِيظُ الْمَشَافِرِ — مَشَافِر is a majāz; literal a camel's lips, figurative lips in general. Clue: a man is named. Formula: ذِكْرُ الْمُقَيَّدِ إِرَادَةُ الْمُطْلَقِ."},
  "ar": ["لَكِنَّكَ زَنْجِيٌّ غَلِيظُ الْمَشَافِرِ"], "notes": ["majaz-mursal"]},
 {"n": 33, "q": {"tr": "Umum alâkası nedir?", "en": "What is the relation of ʿumūm?"},
  "a": {"tr": "Hakikî mânânın umûmî, mecâzî mânânın hususî olmasıdır: رَكِبْتُ دَابَّةً صَاهِلَةً — دَابَّة mecazdır; hakikî mânâsı yerde yürüyen canlı, mecâzî mânâsı at; at, dâbbenin bir ferdidir. Karine: صَاهِلَة kaydı — her canlı kişnemez, at kişner. İfade: ذِكْرُ الْعَامِّ إِرَادَةُ الْخَاصِّ.", "en": "The literal sense is general, the figurative particular: رَكِبْتُ دَابَّةً صَاهِلَةً — دَابَّة is a majāz; literal any beast that walks, figurative a horse; the horse is one of its members. Clue: «neighing» — only a horse neighs. Formula: ذِكْرُ الْعَامِّ إِرَادَةُ الْخَاصِّ."},
  "ar": ["رَكِبْتُ دَابَّةً صَاهِلَةً"], "notes": ["majaz-mursal"]},
 {"n": 34, "q": {"tr": "Husus alâkası nedir?", "en": "What is the relation of khuṣūṣ?"},
  "a": {"tr": "Hakikî mânânın hususî, mecâzî mânânın umûmî olmasıdır: مَا مِنْ فَرَسٍ فِي الْأَرْضِ إِلَّا عَلَى اللهِ رِزْقُهَا — فَرَس mecazdır; hakikî mânâsı at, mecâzî mânâsı dâbbe (her canlı). Karine: إِلَّا عَلَى اللهِ رِزْقُهَا kaydı — her canlının rızkı Allah'a aittir. İfade: ذِكْرُ الْخَاصِّ إِرَادَةُ الْعَامِّ.", "en": "The literal sense is particular, the figurative general: مَا مِنْ فَرَسٍ فِي الْأَرْضِ إِلَّا عَلَى اللهِ رِزْقُهَا — فَرَس is a majāz; literal a horse, figurative every beast. Clue: every creature's provision is God's. Formula: ذِكْرُ الْخَاصِّ إِرَادَةُ الْعَامِّ."},
  "ar": ["مَا مِنْ فَرَسٍ فِي الْأَرْضِ إِلَّا عَلَى اللهِ رِزْقُهَا"], "notes": ["majaz-mursal"]},
 {"n": 35, "q": {"tr": "Kuvvet alâkası nedir?", "en": "What is the relation of quwwa?"},
  "a": {"tr": "Mecâzî mânânın hakikî mânâ ile vasıflanmaya sâlih olmasıdır: شَمَّ زَيْدٌ الْمُسْكِرَ الَّذِي أُرِيقَ — مُسْكِر mecazdır; hakikî mânâsı bilfiil sarhoş edici, mecâzî mânâsı bilkuvve sarhoş edici; dökülen şarap bilfiil sarhoş edici olmaya sâlihtir. Karine: الَّذِي أُرِيقَ kaydı. Yazı bilmeyene kâtip demek de böyledir.", "en": "The figurative sense is fit to be described by the literal: شَمَّ زَيْدٌ الْمُسْكِرَ الَّذِي أُرِيقَ — مُسْكِر is a majāz; literal what actually intoxicates, figurative what could; spilt wine is fit to intoxicate. Clue: «which was spilt». Calling one who cannot yet write a scribe is the same."},
  "ar": ["شَمَّ زَيْدٌ الْمُسْكِرَ الَّذِي أُرِيقَ"], "notes": ["majaz-mursal"]},
 {"n": 36, "q": {"tr": "Lâzımiyyet alâkası nedir?", "en": "What is the relation of lāzimiyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâ için lâzım olmasıdır: أَدَّبْتُ زَيْدًا — أَدَّبْتُ mecazdır; hakikî mânâsı edeplendirdim, mecâzî mânâsı dövdüm (ضَرَبْتُ); edep, dövmenin lâzımıdır. Karine: Zeyd'in edeplenmemiş olması. İfade: ذِكْرُ اللَّازِمِ إِرَادَةُ الْمَلْزُومِ.", "en": "The literal sense is entailed by the figurative: أَدَّبْتُ زَيْدًا — أَدَّبْتُ is a majāz; literal «I disciplined», figurative «I beat»; discipline follows from beating. Clue: Zayd was not disciplined. Formula: ذِكْرُ اللَّازِمِ إِرَادَةُ الْمَلْزُومِ."},
  "ar": ["أَدَّبْتُ زَيْدًا", "ذِكْرُ اللَّازِمِ إِرَادَةُ الْمَلْزُومِ"], "notes": ["majaz-mursal"]},
 {"n": 37, "q": {"tr": "Melzûmiyyet alâkası nedir?", "en": "What is the relation of malzūmiyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâ için melzûm olmasıdır: ضَرَبْتُ زَيْدًا — ضَرَبْتُ mecazdır; hakikî mânâsı dövdüm, mecâzî mânâsı edeplendirdim (أَدَّبْتُ); dövmek, edebin melzûmudur. Karine: Zeyd'in dövülmemiş olması. İfade: ذِكْرُ الْمَلْزُومِ إِرَادَةُ اللَّازِمِ.", "en": "The literal sense entails the figurative: ضَرَبْتُ زَيْدًا — ضَرَبْتُ is a majāz; literal «I beat», figurative «I disciplined»; beating entails discipline. Clue: Zayd was not beaten. Formula: ذِكْرُ الْمَلْزُومِ إِرَادَةُ اللَّازِمِ."},
  "ar": ["ذِكْرُ الْمَلْزُومِ إِرَادَةُ اللَّازِمِ"], "notes": ["majaz-mursal"]},
 {"n": 38, "q": {"tr": "İlliyyet alâkası nedir?", "en": "What is the relation of ʿilliyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâ için illet olmasıdır: أُخْرِجَ النَّارُ قَبْلَ النَّارِ مِنَ الشَّجَرِ الْأَخْضَرِ — birinci نَار mecazdır; hakikî mânâsı ateş, mecâzî mânâsı hararet; ateş hararetin illetidir. Karine: قَبْلَ النَّارِ kaydı — ateşten önce ateş değil hararet çıkar. İfade: ذِكْرُ الْعِلَّةِ إِرَادَةُ الْمَعْلُولِ.", "en": "The literal sense is the cause of the figurative: أُخْرِجَ النَّارُ قَبْلَ النَّارِ مِنَ الشَّجَرِ الْأَخْضَرِ — the first نَار is a majāz; literal fire, figurative heat; fire is the cause of heat. Clue: «before the fire» — heat comes before fire, not fire. Formula: ذِكْرُ الْعِلَّةِ إِرَادَةُ الْمَعْلُولِ."},
  "ar": ["أُخْرِجَ النَّارُ قَبْلَ النَّارِ مِنَ الشَّجَرِ الْأَخْضَرِ"], "notes": ["majaz-mursal"]},
 {"n": 39, "q": {"tr": "Ma'lûliyyet alâkası nedir?", "en": "What is the relation of maʿlūliyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâ için ma'lûl olmasıdır: أُوقِدَتِ الشَّمْعَةُ مِنَ الْحَرَارَةِ — حَرَارَة mecazdır; hakikî mânâsı ısı, mecâzî mânâsı ateş; ısı ateşin ma'lûlüdür. Karine: أُوقِدَتْ'in harârete taallûku — ısıdan mum yakılmaz. İfade: ذِكْرُ الْمَعْلُولِ إِرَادَةُ الْعِلَّةِ.", "en": "The literal sense is the effect of the figurative: أُوقِدَتِ الشَّمْعَةُ مِنَ الْحَرَارَةِ — حَرَارَة is a majāz; literal heat, figurative fire; heat is fire's effect. Clue: a candle is not lit from heat. Formula: ذِكْرُ الْمَعْلُولِ إِرَادَةُ الْعِلَّةِ."},
  "ar": ["أُوقِدَتِ الشَّمْعَةُ مِنَ الْحَرَارَةِ"], "notes": ["majaz-mursal"]},
 {"n": 40, "q": {"tr": "Müteallikiyyet alâkası nedir?", "en": "What is the relation of mutaʿalliqiyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâya müteallik olmasıdır: masdar zikredilip ism-i fâil veya ism-i mef'ûl mânâsı murad edilirse olur. رَجُلٌ ضَرْبٌ — ضَرْب mecazdır; hakikî mânâsı dövmek, mecâzî mânâsı ضَارِب. هَذَا الدِّرْهَمُ ضَرْبُ الْأَمِيرِ — mecâzî mânâsı مَضْرُوب. Karine: hamlin sahih olmaması — adam dövmek olmaz, döven olur. İfade: ذِكْرُ الْمُتَعَلِّقِ إِرَادَةُ الْمُتَعَلَّقِ.", "en": "The literal sense attaches to the figurative — a maṣdar is said and the ism fāʿil or ism mafʿūl meant. رَجُلٌ ضَرْبٌ — ضَرْب is a majāz; literal beating, figurative ضَارِب. هَذَا الدِّرْهَمُ ضَرْبُ الْأَمِيرِ — figurative مَضْرُوب. Clue: the predication is not sound — a man is not a beating. Formula: ذِكْرُ الْمُتَعَلِّقِ إِرَادَةُ الْمُتَعَلَّقِ."},
  "ar": ["رَجُلٌ ضَرْبٌ", "هَذَا الدِّرْهَمُ ضَرْبُ الْأَمِيرِ"], "notes": ["majaz-mursal"]},
 {"n": 41, "q": {"tr": "Müteallakiyyet alâkası nedir?", "en": "What is the relation of mutaʿallaqiyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâya müteallak olmasıdır: ism-i fâil veya ism-i mef'ûl zikredilip masdar mânâsı murad edilirse olur. لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ — كَاذِبَة mecazdır; hakikî mânâsı yalancı, mecâzî mânâsı yalan (كِذْب). بِأَيِّكُمُ الْمَفْتُونُ — مَفْتُون mecazdır; mecâzî mânâsı fitne. Karine: hamlin sahih olmaması. İfade: ذِكْرُ الْمُتَعَلَّقِ إِرَادَةُ الْمُتَعَلِّقِ.", "en": "The figurative sense attaches to the literal — an ism fāʿil or ism mafʿūl is said and the maṣdar meant. لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ — كَاذِبَة is a majāz; literal a liar, figurative a lie. بِأَيِّكُمُ الْمَفْتُونُ — مَفْتُون for the trial itself. Clue: the predication is not sound. Formula: ذِكْرُ الْمُتَعَلَّقِ إِرَادَةُ الْمُتَعَلِّقِ."},
  "ar": ["لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ", "بِأَيِّكُمُ الْمَفْتُونُ"], "notes": ["majaz-mursal"]},
 {"n": 42, "q": {"tr": "Şartiyyet alâkası nedir?", "en": "What is the relation of sharṭiyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânânın şartı olmasıdır: وَمَا كَانَ اللهُ لِيُضِيعَ إِيمَانَكُمْ — إِيمَان mecazdır; hakikî mânâsı inanmak, mecâzî mânâsı namaz; iman namazın şartıdır. Karine: âyetin sebeb-i nüzûlü — ashâb namazlarını sormuşlardı. İfade: ذِكْرُ الشَّرْطِ إِرَادَةُ الْمَشْرُوطِ.", "en": "The literal sense is the condition of the figurative: وَمَا كَانَ اللهُ لِيُضِيعَ إِيمَانَكُمْ — إِيمَان is a majāz; literal faith, figurative the ritual prayer; faith is the prayer's condition. Clue: the occasion of revelation — the Companions had asked about their prayers. Formula: ذِكْرُ الشَّرْطِ إِرَادَةُ الْمَشْرُوطِ."},
  "ar": ["وَمَا كَانَ اللهُ لِيُضِيعَ إِيمَانَكُمْ"], "notes": ["majaz-mursal"]},
 {"n": 43, "q": {"tr": "Meşrûtiyyet alâkası nedir?", "en": "What is the relation of mashrūṭiyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâ için meşrût olmasıdır: قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ — مُصَلِّين mecazdır; hakikî mânâsı namaz kılanlar, mecâzî mânâsı iman edenler; namaz, imanın meşrûtudur. Karine: hitabın kâfirlere olması. İfade: ذِكْرُ الْمَشْرُوطِ إِرَادَةُ الشَّرْطِ.", "en": "The literal sense is conditioned by the figurative: قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ — مُصَلِّين is a majāz; literal those who pray, figurative those who believe; prayer is conditioned on faith. Clue: the words are the unbelievers'. Formula: ذِكْرُ الْمَشْرُوطِ إِرَادَةُ الشَّرْطِ."},
  "ar": ["قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ"], "notes": ["majaz-mursal"]},
 {"n": 44, "q": {"tr": "Dâlliyyet alâkası nedir?", "en": "What is the relation of dālliyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâya delâlet edici olmasıdır: فَهِمْتُ الْأَلْفَاظَ — أَلْفَاظ mecazdır; hakikî mânâsı lafızlar, mecâzî mânâsı mânâlar; lafızlar mânâlara delâlet eder. Karine: فَهِمْتُ'nün elfâza taallûku — lafızlar değil mânâlar anlaşılır. İfade: ذِكْرُ الدَّالِّ إِرَادَةُ الْمَدْلُولِ.", "en": "The literal sense signifies the figurative: فَهِمْتُ الْأَلْفَاظَ — أَلْفَاظ is a majāz; literal the words, figurative the meanings; words signify meanings. Clue: it is meanings, not words, that are understood. Formula: ذِكْرُ الدَّالِّ إِرَادَةُ الْمَدْلُولِ."},
  "ar": ["فَهِمْتُ الْأَلْفَاظَ"], "notes": ["majaz-mursal"]},
 {"n": 45, "q": {"tr": "Medlûliyyet alâkası nedir?", "en": "What is the relation of madlūliyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâ için medlûl olmasıdır: قَرَأْتُ الْمَعَانِيَ — مَعَانِي mecazdır; hakikî mânâsı mânâlar, mecâzî mânâsı lafızlar; mânâlar lafızların medlûlüdür. Karine: قَرَأْتُ'nün meânîye taallûku — mânâlar okunmaz, lafızlar okunur. İfade: ذِكْرُ الْمَدْلُولِ إِرَادَةُ الدَّالِّ.", "en": "The literal sense is what the figurative signifies: قَرَأْتُ الْمَعَانِيَ — مَعَانِي is a majāz; literal the meanings, figurative the words; meanings are what words signify. Clue: one reads words, not meanings. Formula: ذِكْرُ الْمَدْلُولِ إِرَادَةُ الدَّالِّ."},
  "ar": ["قَرَأْتُ الْمَعَانِيَ"], "notes": ["majaz-mursal"]},
 {"n": 46, "q": {"tr": "Bir mecazda bir neviden çok alâka olur mu?", "en": "Can one majāz carry more than one kind of relation?"},
  "a": {"tr": "Bazen olur. İnsan dudağında kullanılan مِشْفَر gibi: رَأَيْتُ زَنْجِيًّا غَلِيظَ الْمِشْفَرِ'de mukayyed olan مِشْفَر zikredilip mutlak olan شَفَة murad edilmekle takyid alâkasına itibar câizdir — mecâz-ı mürsel olur; kalınlıkta müşâbehet alâkasına itibar da câizdir — zencinin dudağı deve dudağına teşbih edilmiş, istiâre-i musarraha-i asliyye olur.", "en": "Sometimes. مِشْفَر for a man's lip: in رَأَيْتُ زَنْجِيًّا غَلِيظَ الْمِشْفَرِ one may reckon the relation of taqyīd — the restricted camel-lip said, the lip in general meant — a majāz mursal; or reckon likeness in thickness — the man's lip likened to a camel's — an istiʿāra muṣarraḥa aṣliyya."},
  "ar": ["رَأَيْتُ زَنْجِيًّا غَلِيظَ الْمِشْفَرِ"], "notes": ["majaz-mursal", "istiara"]},
 {"n": 47, "q": {"tr": "Mecâz-ı lügavînin alâkası kaçtır?", "en": "How many relations has the majāz lughawī?"},
  "a": {"tr": "Mecmuu yirmi sekizdir: müşâbehet ile mecâz-ı mürselin yirmi yedi alâkası. Usul ilminde olduğu gibi bazılarının bazılarına dâhil olduğuna itibarla dokuz da sayılır: müşâbehet, kevn (sâbık), evl (lâhık), istidad (kuvvet), hulûl (masdariyyet, mazhariyyet, mücâveret, hâlliyyet, mahalliyyet), cüz'iyyet (ıtlak, takyid, umum, husus), külliyyet, sebebiyyet (müsebbebiyyet, illiyyet, ma'lûliyyet, lâzımiyyet, melzûmiyyet), şartiyyet (meşrûtiyyet, müteallikiyyet, müteallakiyyet, dâlliyyet, medlûliyyet).", "en": "Twenty-eight in all: likeness plus the twenty-seven of the majāz mursal. Counted as in uṣūl, with some folded into others, they are nine: likeness, kawn (sābiq), awl (lāḥiq), istiʿdād (quwwa), ḥulūl (maṣdariyya, maẓhariyya, mujāwara, ḥālliyya, maḥalliyya), juzʾiyya (iṭlāq, taqyīd, ʿumūm, khuṣūṣ), kulliyya, sababiyya (musabbabiyya, ʿilliyya, maʿlūliyya, lāzimiyya, malzūmiyya), sharṭiyya (mashrūṭiyya, mutaʿalliqiyya, mutaʿallaqiyya, dālliyya, madlūliyya)."},
  "ar": ["عَلَاقَاتُ الْمَجَازِ اللُّغَوِيِّ ثَمَانِيَةٌ وَعِشْرُونَ"], "notes": ["majaz-mursal", "anwa-al-majaz"]},
]
